#[test]
fn sparse_addresses_never_support_automatic_links() {
    for address in [
        "london",
        "sw1a 1aa",
        "london sw1a 1aa",
        "1 sw1a 1aa",
        "1 london",
    ] {
        let result = resolve(
            &input(vec![
                payer(observation(
                    1,
                    Some("john smith"),
                    Some(address),
                    None,
                    None,
                )),
                payer(observation(
                    2,
                    Some("john smith"),
                    Some(address),
                    None,
                    None,
                )),
            ]),
            0.9999,
        );
        assert_ne!(
            result.observations[0].identity_id,
            result.observations[1].identity_id
        );
        assert!(
            result
                .pairs
                .iter()
                .all(|edge| edge.disposition == PairDisposition::Review)
        );
    }
}

